CREATE TABLE "app"."fiche_index" (
	"food_analysis_id" uuid PRIMARY KEY NOT NULL,
	"type" text NOT NULL,
	"court" text NOT NULL,
	"cle" text NOT NULL,
	"nom" text NOT NULL,
	"actif" boolean DEFAULT true NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "fiche_index_court_unique" UNIQUE("court"),
	CONSTRAINT "fiche_index_cle_unique" UNIQUE("cle")
);
